-- Multi-tenant conversion: Settings -> Merchant, add merchantId to every other
-- table, backfill all existing rows to the one existing merchant, then tighten
-- constraints. Hand-authored (not autogenerated) because of the rename + PK
-- changes involved.

-- ===== 1. Settings -> Merchant =====
ALTER TABLE "Settings" RENAME TO "Merchant";
ALTER TABLE "Merchant" RENAME CONSTRAINT "Settings_pkey" TO "Merchant_pkey";

-- id was a fixed @default(1) singleton column; make it a real autoincrement
-- sequence so new signups get auto-generated ids. The existing row keeps id=1.
CREATE SEQUENCE IF NOT EXISTS "Merchant_id_seq" OWNED BY "Merchant"."id";
SELECT setval('"Merchant_id_seq"', (SELECT COALESCE(MAX(id), 1) FROM "Merchant"));
ALTER TABLE "Merchant" ALTER COLUMN "id" SET DEFAULT nextval('"Merchant_id_seq"');

ALTER TABLE "Merchant" ADD COLUMN "businessType" TEXT;
ALTER TABLE "Merchant" ADD COLUMN "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Merchant" ALTER COLUMN "location" DROP NOT NULL;

-- email is already populated + verified for the sole existing row from earlier
-- work this session, so this is safe to tighten immediately.
ALTER TABLE "Merchant" ALTER COLUMN "email" SET NOT NULL;
ALTER TABLE "Merchant" ADD CONSTRAINT "Merchant_email_key" UNIQUE ("email");

-- ===== 2. Plain-id-PK tables: add merchantId, backfill to merchant id 1, lock it down =====
ALTER TABLE "Staff" ADD COLUMN "merchantId" INTEGER;
UPDATE "Staff" SET "merchantId" = 1;
ALTER TABLE "Staff" ALTER COLUMN "merchantId" SET NOT NULL;
CREATE INDEX "Staff_merchantId_idx" ON "Staff"("merchantId");

ALTER TABLE "Booking" ADD COLUMN "merchantId" INTEGER;
UPDATE "Booking" SET "merchantId" = 1;
ALTER TABLE "Booking" ALTER COLUMN "merchantId" SET NOT NULL;
CREATE INDEX "Booking_merchantId_idx" ON "Booking"("merchantId");

ALTER TABLE "Product" ADD COLUMN "merchantId" INTEGER;
UPDATE "Product" SET "merchantId" = 1;
ALTER TABLE "Product" ALTER COLUMN "merchantId" SET NOT NULL;
CREATE INDEX "Product_merchantId_idx" ON "Product"("merchantId");

ALTER TABLE "Service" ADD COLUMN "merchantId" INTEGER;
UPDATE "Service" SET "merchantId" = 1;
ALTER TABLE "Service" ALTER COLUMN "merchantId" SET NOT NULL;
CREATE INDEX "Service_merchantId_idx" ON "Service"("merchantId");

ALTER TABLE "LeaveRecord" ADD COLUMN "merchantId" INTEGER;
UPDATE "LeaveRecord" SET "merchantId" = 1;
ALTER TABLE "LeaveRecord" ALTER COLUMN "merchantId" SET NOT NULL;
CREATE INDEX "LeaveRecord_merchantId_idx" ON "LeaveRecord"("merchantId");

-- ===== 3. Natural-key-PK tables: add merchantId, backfill, swap PK to composite =====
ALTER TABLE "Schedule" ADD COLUMN "merchantId" INTEGER;
UPDATE "Schedule" SET "merchantId" = 1;
ALTER TABLE "Schedule" ALTER COLUMN "merchantId" SET NOT NULL;
ALTER TABLE "Schedule" DROP CONSTRAINT "Schedule_pkey";
ALTER TABLE "Schedule" ADD CONSTRAINT "Schedule_pkey" PRIMARY KEY ("merchantId", "staffId");

ALTER TABLE "CustomerExtra" ADD COLUMN "merchantId" INTEGER;
UPDATE "CustomerExtra" SET "merchantId" = 1;
ALTER TABLE "CustomerExtra" ALTER COLUMN "merchantId" SET NOT NULL;
ALTER TABLE "CustomerExtra" DROP CONSTRAINT "CustomerExtra_pkey";
ALTER TABLE "CustomerExtra" ADD CONSTRAINT "CustomerExtra_pkey" PRIMARY KEY ("merchantId", "phone");

ALTER TABLE "CustomerNote" ADD COLUMN "merchantId" INTEGER;
UPDATE "CustomerNote" SET "merchantId" = 1;
ALTER TABLE "CustomerNote" ALTER COLUMN "merchantId" SET NOT NULL;
ALTER TABLE "CustomerNote" DROP CONSTRAINT "CustomerNote_pkey";
ALTER TABLE "CustomerNote" ADD CONSTRAINT "CustomerNote_pkey" PRIMARY KEY ("merchantId", "phone");

ALTER TABLE "ClosedDate" ADD COLUMN "merchantId" INTEGER;
UPDATE "ClosedDate" SET "merchantId" = 1;
ALTER TABLE "ClosedDate" ALTER COLUMN "merchantId" SET NOT NULL;
ALTER TABLE "ClosedDate" DROP CONSTRAINT "ClosedDate_pkey";
ALTER TABLE "ClosedDate" ADD CONSTRAINT "ClosedDate_pkey" PRIMARY KEY ("merchantId", "date");

ALTER TABLE "OpenOverride" ADD COLUMN "merchantId" INTEGER;
UPDATE "OpenOverride" SET "merchantId" = 1;
ALTER TABLE "OpenOverride" ALTER COLUMN "merchantId" SET NOT NULL;
ALTER TABLE "OpenOverride" DROP CONSTRAINT "OpenOverride_pkey";
ALTER TABLE "OpenOverride" ADD CONSTRAINT "OpenOverride_pkey" PRIMARY KEY ("merchantId", "date");

ALTER TABLE "ClosedWeekday" ADD COLUMN "merchantId" INTEGER;
UPDATE "ClosedWeekday" SET "merchantId" = 1;
ALTER TABLE "ClosedWeekday" ALTER COLUMN "merchantId" SET NOT NULL;
ALTER TABLE "ClosedWeekday" DROP CONSTRAINT "ClosedWeekday_pkey";
ALTER TABLE "ClosedWeekday" ADD CONSTRAINT "ClosedWeekday_pkey" PRIMARY KEY ("merchantId", "weekday");
